function mk_upload_image(string $field, string $prefix, array &$errors, ?array $file=null): ?string {
    $f=$file ?? ($_FILES[$field] ?? null);
    if (!is_array($f) || ($f['error'] ?? UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE) return null;
    if (($f['error'] ?? 1)!==UPLOAD_ERR_OK || !is_uploaded_file($f['tmp_name'] ?? '')) { $errors[]='Caricamento immagine non riuscito: '.$field.'.'; return null; }
    $info=@getimagesize($f['tmp_name']); $mime=$info['mime'] ?? '';
    $map=['image/jpeg'=>'jpg','image/png'=>'png','image/gif'=>'gif','image/webp'=>'webp','image/x-icon'=>'ico','image/vnd.microsoft.icon'=>'ico'];
    if (!$info || !isset($map[$mime]) || (int)($f['size']??0)>8*1024*1024) { $errors[]='Formato non valido o file superiore a 8 MB: '.$field.'. Usa JPG, PNG, GIF o WebP.'; return null; }
    $dir=dirname(__DIR__,2).'/uploads/images'; if(!is_dir($dir) && !mkdir($dir,0755,true)){ $errors[]='Cartella uploads/images non disponibile.'; return null; }
    $name=$prefix.'-'.bin2hex(random_bytes(10)).'.'.$map[$mime];
    if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name)){ $errors[]='Impossibile salvare il file: '.$field.'.'; return null; }
    return 'uploads/images/'.$name;
}
function mk_nested_file(array $files, string $group, string $key): ?array {
    if(empty($files[$group]) || !isset($files[$group]['name'][$key])) return null;
    $out=[]; foreach(['name','type','tmp_name','error','size'] as $part) $out[$part]=$files[$group][$part][$key]??null; return $out;
}

/** Sincronizza la configurazione visuale con le impostazioni native di MercurioCMS.
 * La tabella settings è la fonte persistente condivisa: disattivando Merkury,
 * il CMS conserva quindi colori, identità e risorse senza dipendere dal plugin.
 */
function mk_sync_cms_settings(array $s): void {
    // I valori condivisi sono scritti nelle chiavi native ufficiali del CMS.
    // Le altre preferenze restano nel JSON del tema e non vengono duplicate.
    $map = [
        'color_primary' => (string)($s['primary_color'] ?? ''),
        'color_background' => (string)($s['paper_color'] ?? ''),
        'color_text' => (string)($s['ink_color'] ?? ''),
        'color_header_bg' => (string)($s['chrome_color'] ?? ''),
        'color_hero_eyebrow' => (string)($s['accent_color'] ?? ''),
        'hero_eyebrow_text' => trim((string)($s['intro_eyebrow'] ?? '')),
        'hero_title_text' => trim((string)($s['intro_title'] ?? '')),
        'site_description' => trim((string)($s['intro_text'] ?? '')),
    ];
    $nativeKeys = ['color_surface','color_footer_bg','color_footer_text','color_header_text','color_hero_bg','color_hero_title','color_hero_text'];
    foreach ($nativeKeys as $key) {
        $value = (string)($s['native_colors'][$key] ?? '');
        if (preg_match('/^#[0-9A-Fa-f]{6}$/', $value)) $map[$key] = strtoupper($value);
    }
    foreach ($map as $key => $value) {
        if (str_starts_with($key, 'color_')) {
            if (preg_match('/^#[0-9A-Fa-f]{6}$/', $value)) cms_set_setting($key, strtoupper($value));
        } else {
            cms_set_setting($key, $value);
        }
    }
    cms_set_setting('merkury_cms_sync_version', '1.0.3');
}

